<template>
  <div class="page-container gpm-page">
    <div class="page-head"><div><h2>地块管理</h2><p>维护确权、流转地块台账，地块关联主体统一在种植主体管理中维护。</p></div><el-button type="primary" @click="openCreate">新增地块</el-button></div>
    <div class="panel">
      <div class="panel-title"><span class="title-text">地块台账</span><span class="title-extra">共 {{ plots.length }} 块</span></div>
      <el-form :inline="true" class="filters"><el-form-item label="关键字"><el-input v-model="filters.keyword" clearable placeholder="地块名称/编号/主体" /></el-form-item><el-form-item label="来源"><el-select v-model="filters.source" clearable placeholder="全部" style="width:140px"><el-option label="确权地块" value="确权"/><el-option label="流转地块" value="流转"/></el-select></el-form-item><el-form-item label="关联状态"><el-select v-model="filters.status" clearable placeholder="全部" style="width:140px"><el-option label="已关联" value="已关联"/><el-option label="待确认" value="待确认"/></el-select></el-form-item><el-button type="primary" @click="loadPlots">查询</el-button><el-button @click="reset">重置</el-button></el-form>
      <el-table :data="plots" stripe height="calc(100vh - 300px)"><el-table-column prop="id" label="地块编号" width="130"/><el-table-column prop="name" label="地块名称" min-width="170" show-overflow-tooltip/><el-table-column prop="area" label="地块面积(亩)" width="110"/><el-table-column prop="nameColor" label="名称颜色" width="90"><template #default="{ row }"><span class="color-dot" :style="{ backgroundColor: row.nameColor || '#409eff' }"/>{{ row.nameColor || '默认' }}</template></el-table-column><el-table-column prop="unitName" label="所属单位" min-width="140" show-overflow-tooltip/><el-table-column prop="manager" label="经营人员" width="100"/><el-table-column prop="cropName" label="种植作物" width="100"/><el-table-column prop="variety" label="种植品种" width="110"/><el-table-column prop="purpose" label="地块用途" width="110"/><el-table-column prop="plotType" label="地块类型" width="100"/><el-table-column prop="location" label="地块经纬度" min-width="160" show-overflow-tooltip/><el-table-column label="关联状态" width="100"><template #default="{ row }"><el-tag size="small" :type="row.relationStatus === '已关联' ? 'success' : 'warning'">{{ row.relationStatus }}</el-tag></template></el-table-column><el-table-column label="操作" width="240" fixed="right"><template #default="{ row }"><el-button link type="primary" @click="openView(row)">查看详情</el-button><el-button link @click="openEdit(row)">编辑</el-button></template></el-table-column></el-table>
    </div>
    <el-drawer v-model="visible" :title="drawerTitle" size="480px">
      <el-form v-if="mode !== 'view'" ref="formRef" :model="form" :rules="rules" label-width="110px"><el-form-item label="地块名称" prop="name"><el-input v-model="form.name"/></el-form-item><el-form-item label="地块面积" prop="area"><el-input-number v-model="form.area" :min="0.1" :precision="1" style="width:100%"/><span class="unit-tip">亩</span></el-form-item><el-form-item label="地块名称颜色" prop="nameColor"><el-color-picker v-model="form.nameColor"/></el-form-item><el-form-item label="所属单位" prop="unitName"><el-input v-model="form.unitName"/></el-form-item><el-form-item label="经营人员"><el-input v-model="form.manager"/></el-form-item><el-form-item label="种植作物" prop="crop"><el-select v-model="form.crop" style="width:100%"><el-option label="小麦" value="wheat"/><el-option label="水稻" value="rice"/><el-option label="玉米" value="corn"/><el-option label="大豆" value="soybean"/><el-option label="青贮玉米" value="silage_corn"/></el-select></el-form-item><el-form-item label="种植品种"><el-input v-model="form.variety" placeholder="请输入种植品种"/></el-form-item><el-form-item label="地块用途"><el-select v-model="form.purpose" clearable style="width:100%"><el-option label="粮食种植" value="粮食种植"/><el-option label="良种繁育" value="良种繁育"/><el-option label="试验示范" value="试验示范"/></el-select></el-form-item><el-form-item label="地块类型" prop="plotType"><el-select v-model="form.plotType" style="width:100%"><el-option label="确权地块" value="确权地块"/><el-option label="流转地块" value="流转地块"/><el-option label="其他地块" value="其他地块"/></el-select></el-form-item><el-form-item label="地块经纬度" prop="location"><el-input v-model="form.location" placeholder="如：115.622000, 33.160000"/></el-form-item><el-form-item label="地块轮廓"><el-input v-model="form.boundary" type="textarea" :rows="3" placeholder="请输入地块轮廓坐标或在地图中绘制"/></el-form-item></el-form>
      <el-descriptions v-else :column="1" border><el-descriptions-item label="地块编号">{{ current?.id }}</el-descriptions-item><el-descriptions-item label="地块名称">{{ current?.name }}</el-descriptions-item><el-descriptions-item label="地块面积">{{ current?.area }} 亩</el-descriptions-item><el-descriptions-item label="地块名称颜色"><span class="color-dot" :style="{ backgroundColor: current?.nameColor || '#409eff' }"/>{{ current?.nameColor || '默认' }}</el-descriptions-item><el-descriptions-item label="所属单位">{{ current?.unitName }}</el-descriptions-item><el-descriptions-item label="经营人员">{{ current?.manager || '暂无' }}</el-descriptions-item><el-descriptions-item label="种植作物">{{ current?.cropName || '未种植' }}</el-descriptions-item><el-descriptions-item label="种植品种">{{ current?.variety || '暂无' }}</el-descriptions-item><el-descriptions-item label="地块用途">{{ current?.purpose || '暂无' }}</el-descriptions-item><el-descriptions-item label="地块类型">{{ current?.plotType || '暂无' }}</el-descriptions-item><el-descriptions-item label="地块经纬度">{{ current?.location || '暂无' }}</el-descriptions-item><el-descriptions-item label="地块轮廓">{{ current?.boundary || '暂无' }}</el-descriptions-item><el-descriptions-item label="经营主体">{{ current?.subjectName || '未关联' }}</el-descriptions-item></el-descriptions>
      <template #footer><el-button @click="visible=false">关闭</el-button><el-button v-if="mode !== 'view'" type="primary" @click="submitPlot">保存</el-button><el-button v-if="mode === 'view' && current" @click="openEdit(current)">编辑</el-button></template>
    </el-drawer>
  </div>
</template>
<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { fetchPlanPlots, fetchSubjectPlotRelations, savePlanPlot } from '@/api/gpm'
import { useUserStore } from '@/stores/user'

const userStore = useUserStore(); const plots = ref([]); const visible = ref(false); const current = ref(null); const mode = ref('view'); const formRef = ref(null); const filters = reactive({ keyword: '', source: '', status: '' }); const form = reactive({ id: '', name: '', area: 0, nameColor: '#409eff', unitName: '', manager: '', crop: 'wheat', variety: '', purpose: '粮食种植', plotType: '确权地块', location: '', boundary: '', regionName: '', source: '确权' }); const rules = { name: [{ required: true, message: '请输入地块名称' }], area: [{ required: true, message: '请输入地块面积' }], unitName: [{ required: true, message: '请输入所属单位' }], crop: [{ required: true, message: '请选择种植作物' }], plotType: [{ required: true, message: '请选择地块类型' }], location: [{ required: true, message: '请输入地块经纬度' }] }; const drawerTitle = computed(() => mode.value === 'create' ? '新增地块' : mode.value === 'edit' ? '编辑地块' : `地块详情${current.value?.name ? `：${current.value.name}` : ''}`)
const loadPlots = async () => { const [plotRows, relationRows] = await Promise.all([fetchPlanPlots(userStore.role), fetchSubjectPlotRelations(userStore.role, filters)]); const relationMap = Object.fromEntries(relationRows.map((item) => [item.plotId, item])); plots.value = plotRows.map((plot) => ({ ...plot, ...relationMap[plot.id], relationId: relationMap[plot.id]?.id, name: plot.name || plot.plotName, relationStatus: relationMap[plot.id]?.relationStatus || (plot.status === 'implemented' ? '已关联' : '待确认'), subjectName: relationMap[plot.id]?.subjectName || plot.subjectName, area: plot.area || plot.areaMu })).filter((item) => (!filters.keyword || `${item.id}${item.name}${item.subjectName}`.includes(filters.keyword)) && (!filters.source || item.source === filters.source) && (!filters.status || item.relationStatus === filters.status)) }
const reset = () => { Object.assign(filters, { keyword: '', source: '', status: '' }); loadPlots() }
const openView = (row) => { current.value = row; mode.value = 'view'; visible.value = true }
const openEdit = (row) => { current.value = row; Object.assign(form, { id: row.id, name: row.name, area: row.area, nameColor: row.nameColor || '#409eff', unitName: row.unitName || row.regionName || '', manager: row.manager || '', crop: row.crop || 'wheat', variety: row.variety || '', purpose: row.purpose || '粮食种植', plotType: row.plotType || `${row.source || '确权'}地块`, location: row.location || '', boundary: row.boundary || '', regionName: row.regionName || row.unitName || '', source: row.source || '确权' }); mode.value = 'edit'; visible.value = true }
const openCreate = () => { current.value = null; Object.assign(form, { id: '', name: '', area: 0, nameColor: '#409eff', unitName: userStore.regionName || '', manager: '', crop: 'wheat', variety: '', purpose: '粮食种植', plotType: '确权地块', location: '', boundary: '', regionName: userStore.regionName || '', source: '确权' }); mode.value = 'create'; visible.value = true }
const submitPlot = async () => { await formRef.value.validate(); const result = await savePlanPlot({ ...form, role: userStore.role }); if (!result.success) return ElMessage.warning(result.message); ElMessage.success('地块已保存'); visible.value = false; await loadPlots() }
onMounted(loadPlots)
</script>
<style lang="scss" scoped>
.gpm-page{gap:12px;overflow:auto}.page-head{display:flex;justify-content:space-between;align-items:flex-start}h2{margin:4px 0;color:var(--ah-text);font-size:22px}.page-head p{color:var(--ah-text-secondary);font-size:13px}.filters{display:flex;align-items:center;flex-wrap:wrap}.filters :deep(.el-form-item){margin-bottom:12px;margin-right:12px}.color-dot{display:inline-block;width:12px;height:12px;margin-right:5px;border:1px solid #dcdfe6;border-radius:50%;vertical-align:-1px}.unit-tip{margin-left:8px;color:var(--ah-text-secondary);font-size:12px}
</style>
